if($type==='pm'){$r=uc_pm_list($u['uid'],$page,20,'inbox','privatepm',150);respond(['list'=>is_array($r)?($r['data']??[]):[],'page'=>paging((int)($r['count']??0)),'unread'=>['pm'=>(int)uc_pm_checknew($u['uid']),'notice'=>(int)$u['newprompt']]]);}
if(!in_array($type,['system','notice'],true))respond(null,422,'消息类别无效');$category=$type==='system'?' AND authorid=0':' AND authorid>0';$exists=one('SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?', [str_replace('`','',table('app_notice_hidden'))]);if($exists)$category.=' AND id NOT IN (SELECT id FROM '.table('app_notice_hidden').' WHERE uid='.(int)$u['uid'].')';$total=one('SELECT COUNT(*) n FROM '.table('home_notification').' WHERE uid=?'.$category,[$u['uid']]);$p=paging($total['n']);$offset=($p['page']-1)*20;$list=rows('SELECT id,type,authorid,author,note,dateline,`new`,from_id,from_idtype FROM '.table('home_notification').' WHERE uid=?'.$category.' ORDER BY dateline DESC,id DESC LIMIT '.$offset.',20',[$u['uid']]);foreach($list as &$n){$n['content_html']=clean_html($n['note']);unset($n['note']);$n['is_read']=!(bool)$n['new'];}unset($n);respond(['list'=>$list,'page'=>$p,'unread'=>['notice'=>(int)$u['newprompt'],'pm'=>(int)$u['newpm']]]);
